-- Additive platform-core baseline. Existing storefront, product, order and media
-- tables are intentionally untouched. All IDs are generated by PostgreSQL.
CREATE TABLE IF NOT EXISTS sites (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id text NOT NULL,
  name text NOT NULL,
  slug text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  domain text,
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT sites_status_check CHECK (status IN ('draft', 'published', 'archived'))
);

CREATE UNIQUE INDEX IF NOT EXISTS sites_owner_slug_unique ON sites (owner_id, slug);
CREATE UNIQUE INDEX IF NOT EXISTS sites_domain_unique ON sites (domain) WHERE domain IS NOT NULL;
CREATE INDEX IF NOT EXISTS sites_owner_created_idx ON sites (owner_id, created_at);

CREATE TABLE IF NOT EXISTS pages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site_id uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
  title text NOT NULL,
  slug text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  sort_order integer NOT NULL DEFAULT 0,
  seo jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pages_status_check CHECK (status IN ('draft', 'published'))
);

CREATE UNIQUE INDEX IF NOT EXISTS pages_site_slug_unique ON pages (site_id, slug);
CREATE INDEX IF NOT EXISTS pages_site_order_idx ON pages (site_id, sort_order);

CREATE TABLE IF NOT EXISTS page_blocks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
  type text NOT NULL,
  schema_version integer NOT NULL DEFAULT 1,
  position integer NOT NULL DEFAULT 0,
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT page_blocks_schema_version_check CHECK (schema_version > 0),
  CONSTRAINT page_blocks_config_object_check CHECK (jsonb_typeof(config) = 'object')
);

CREATE INDEX IF NOT EXISTS page_blocks_page_position_idx ON page_blocks (page_id, position);
